func TestEnumUpdateHostRequestStatus(t *testing.T) {
	t.Run("NewFromString_active", func(t *testing.T) {
		t.Parallel()
		val, err := NewUpdateHostRequestStatusFromString("active")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, UpdateHostRequestStatus("active"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_disabled", func(t *testing.T) {
		t.Parallel()
		val, err := NewUpdateHostRequestStatusFromString("disabled")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, UpdateHostRequestStatus("disabled"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewUpdateHostRequestStatusFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewUpdateHostRequestStatusFromString("active")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}
